<script setup lang="ts">
import {ref,computed,onMounted,onUnmounted,watch,nextTick} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import {ArrowUp,Square,SlidersHorizontal,RefreshCw} from 'lucide-vue-next'
import {api,newKey} from '../api'
import {cacheGet,cacheSet} from '../platform/bridge'
import {useRequestScope} from '../platform/request-scope'
import {useApp} from '../stores/app'
import {worldApi} from '../world/api'
import type {WorldTask} from '../world/types'
import PageHeader from '../workspace/PageHeader.vue'
import Sheet from '../components/Sheet.vue'
import PublicStreamText from '../components/PublicStreamText.vue'
import WorldAppearanceProvider from '../components/WorldAppearanceProvider.vue'
import CharacterAvatar from '../components/CharacterAvatar.vue'
import AccountAvatar from '../components/AccountAvatar.vue'
import ModelControlButton from './ModelControlButton.vue'
import PlaySettings from './PlaySettings.vue'
import PrivateBackup from '../components/PrivateBackup.vue'
import TaskProgress from '../experience/TaskProgress.vue'
import PersonaControl from '../characters/PersonaControl.vue'
import ReadingPreferencePanel from '../components/ReadingPreferencePanel.vue'
import {readingStyle} from '../reader/reading-preference'
import {authorizedBlob,saveBlob,safeFileName} from '../platform/download'
import type {WorldChat,ChatMessage,ChatInjection} from './types'
import {restoreChatDraft,type ChatDraft,type ChatIntent} from './chat-draft'
const route=useRoute(),router=useRouter(),id=String(route.params.sessionId),root='/play-controls/world-chats/'+id,capture=useRequestScope(),app=useApp(),chat=ref<WorldChat>(),task=ref<WorldTask>(),draft=ref(''),busy=ref(false),error=ref(''),notice=ref(''),settings=ref(false),sourceConfirm=ref(false),renaming=ref(false),name=ref(''),log=ref<HTMLElement>()
const modelSettings=ref<InstanceType<typeof PlaySettings>>(),modelButton=ref<InstanceType<typeof ModelControlButton>>()
const backup=ref(false),deleting=ref(false),sourcePreview=ref<{fromTime:string;toTime:string;changed:boolean;addedFacts:{title:string;text:string}[]}>(),messageSearch=ref(''),matches=ref<ChatMessage[]>([]),sourceOpen=ref(false),locatedSequence=ref(0),searching=ref(false),olderBusy=ref(false),forkSequence=ref<number|null>(null),forking=ref(false)
function askFork(sequence:number){forkSequence.value=sequence}
function cancelFork(){if(!forking.value)forkSequence.value=null}
async function confirmFork(){
  if(forkSequence.value===null||forking.value||!chat.value)return
  const scope=capture()
  forking.value=true;error.value=''
  try{
    const result=await api<{sessionId:string;name?:string}>('/play-controls/world-chats/'+chat.value.id+'/fork',{method:'POST',key:newKey(),body:{sequence:forkSequence.value}})
    if(!scope.valid())return
    forkSequence.value=null
    await router.push('/conversations/world/'+result.sessionId)
  }catch(cause){
    if(scope.valid())error.value=(cause as Error).message
  }finally{
    if(scope.valid())forking.value=false
  }
}
async function closeSettings(){if(await modelSettings.value?.requestClose())settings.value=false}
const intent=ref<ChatIntent|null>(null),running=computed(()=>!!chat.value?.pendingTaskId),sourceLink=computed(()=>chat.value?'/worlds/'+chat.value.worldId+'/play?line='+chat.value.lineId:'/explore'),slot=computed(()=>chat.value?'world-chat-draft:'+chat.value.worldId+':'+chat.value.lineId+':'+id:'')
const pendingMessage=computed(()=>{const messages=chat.value?.messages||[];for(let index=messages.length-1;index>=0;index--){const message=messages[index];if(message.role==='assistant'&&message.status==='pending')return message}return null}),lastAssistantId=computed(()=>{const messages=chat.value?.messages||[];for(let index=messages.length-1;index>=0;index--){if(messages[index].role==='assistant')return messages[index].id}return ''}),editingSequence=ref<number|null>(null),editText=ref(''),editBusy=ref(false)
const personaId=ref<string|null>(null),memoryOpen=ref(false),injection=ref<ChatInjection|null>(null),injectionLoading=ref(false),injectionError=ref(''),exporting=ref(false),memoryBefore=ref(0)
let timer:ReturnType<typeof setTimeout>|undefined,disposed=false,loadedDraft=false
async function persist(){if(slot.value)await cacheSet(slot.value,{worldId:chat.value!.worldId,lineId:chat.value!.lineId,draft:draft.value,intent:intent.value})}
watch(draft,()=>{if(loadedDraft)void persist().catch(()=>{error.value='输入暂时无法保存在此设备，请保持页面打开。'})})
function bottom(){void nextTick(()=>{const element=log.value;if(element&&element.scrollHeight-element.scrollTop-element.clientHeight<500)element.scrollTop=element.scrollHeight})}
async function older(){if(!chat.value?.messages?.length||olderBusy.value)return;olderBusy.value=true;const scope=capture();try{const result=await api<{items:ChatMessage[]}>(root+'/messages?before='+chat.value.messages[0].sequence);if(scope.valid()&&!disposed)chat.value.messages=[...result.items.filter(m=>!chat.value!.messages!.some(x=>x.id===m.id)),...chat.value.messages]}catch(e){if(scope.valid()&&!disposed)error.value=(e as Error).message}finally{if(scope.valid()&&!disposed)olderBusy.value=false}}
async function fetchChat(){const scope=capture(),result=await api<WorldChat>(root);if(!scope.valid()||disposed)return;chat.value=result;name.value=result.name;personaId.value=result.personaId??null;if(!loadedDraft){const saved=await cacheGet<ChatDraft>(slot.value);if(!scope.valid()||disposed)return;const restored=restoreChatDraft(saved,result.messages||[]);draft.value=restored.draft;intent.value=restored.intent;loadedDraft=true;if(saved?.intent&&!restored.intent)await persist()}bottom()}
function schedule(delay=700){clearTimeout(timer);if(!disposed)timer=setTimeout(()=>void poll(),delay)}
async function poll(){const scope=capture(),pending=chat.value?.pendingTaskId;if(!pending||disposed)return;try{const result=await worldApi<WorldTask>('/tasks/'+pending);if(!scope.valid()||disposed)return;task.value=result;await fetchChat();if(!scope.valid()||disposed)return;bottom();if(['succeeded','failed','cancelled'].includes(result.state)&&result.persistenceState!=='recoverable'){if(result.state!=='succeeded')notice.value=result.state==='cancelled'?'已停止，收到的回复已保留。':'这次回复没有完整完成，已收到的内容会保留。';return}schedule(700)}catch(e){if(scope.valid()&&!disposed){error.value=(e as Error).message;schedule(2500)}}}
async function load(){const scope=capture();error.value='';try{await fetchChat();if(scope.valid()&&!disposed)await locateSource();if(scope.valid()&&!disposed&&chat.value?.pendingTaskId)schedule(0)}catch(e){if(scope.valid()&&!disposed)error.value=(e as Error).message}}
async function send(){if(busy.value||running.value||!app.online||(!draft.value.trim()&&!intent.value))return;const scope=capture();busy.value=true;error.value='';notice.value='';try{if(!intent.value)intent.value={message:draft.value.trim(),turnId:newKey(),key:newKey()};await persist();if(!scope.valid()||disposed)return;const current=intent.value!;await api(root+'/send',{method:'POST',body:{message:current.message,turnId:current.turnId},key:current.key});if(!scope.valid()||disposed)return;intent.value=null;draft.value='';await persist();task.value=undefined;await fetchChat();schedule(0)}catch(e){if(scope.valid()&&!disposed)error.value=(e as Error).message}finally{if(scope.valid()&&!disposed)busy.value=false}}
async function stop(){if(!chat.value?.pendingTaskId)return;const scope=capture();try{await worldApi('/tasks/'+chat.value.pendingTaskId+'/cancel',{method:'POST',body:{}});if(scope.valid()&&!disposed){notice.value='正在停止并保存已收到的内容…';schedule(0)}}catch(e){if(scope.valid()&&!disposed)error.value=(e as Error).message}}
async function update(advance:boolean){if(!chat.value||busy.value||running.value)return;const scope=capture();busy.value=true;error.value='';try{const result=await api<WorldChat>(root,{method:'PATCH',key:newKey(),body:{expectedVersion:chat.value.version,...(advance?{updateSource:true}:{name:name.value})}});if(scope.valid()&&!disposed){chat.value={...result,messages:chat.value.messages};sourceConfirm.value=false;renaming.value=false;notice.value=advance?'来源已更新到当前主线进度，以后的消息会使用新资料。历史消息保留原来源。':'对话名称已保存。'}}catch(e){if(scope.valid()&&!disposed)error.value=(e as Error).message}finally{if(scope.valid()&&!disposed)busy.value=false}}

function startEdit(message:ChatMessage){if(running.value||busy.value)return;editingSequence.value=message.sequence;editText.value=message.text}
function cancelEdit(){editingSequence.value=null;editText.value=''}
async function saveEdit(){if(editingSequence.value===null||editBusy.value||running.value)return;const sequence=editingSequence.value,scope=capture();editBusy.value=true;error.value='';notice.value='';try{await api(root+'/messages/'+sequence,{method:'PATCH',key:newKey(),body:{text:editText.value}});if(!scope.valid()||disposed)return;editingSequence.value=null;task.value=undefined;await fetchChat();schedule(0)}catch(e){if(scope.valid()&&!disposed)error.value=(e as Error).message}finally{if(scope.valid()&&!disposed)editBusy.value=false}}
async function regenerate(){if(running.value||busy.value)return;const scope=capture();busy.value=true;error.value='';notice.value='';try{await api(root+'/regenerate',{method:'POST',key:newKey(),body:{}});if(!scope.valid()||disposed)return;task.value=undefined;await fetchChat();schedule(0)}catch(e){if(scope.valid()&&!disposed)error.value=(e as Error).message}finally{if(scope.valid()&&!disposed)busy.value=false}}
async function previewSource(){const scope=capture();try{sourcePreview.value=await api(root+'/source-preview');if(scope.valid())sourceConfirm.value=true}catch(e){if(scope.valid())error.value=(e as Error).message}}
async function archive(){if(!chat.value||running.value||busy.value)return;const scope=capture();busy.value=true;try{const result=await api<WorldChat>(root,{method:'PATCH',key:newKey(),body:{expectedVersion:chat.value.version,status:chat.value.status==='archived'?'active':'archived'}});if(scope.valid())chat.value={...result,messages:chat.value.messages}}catch(e){if(scope.valid())error.value=(e as Error).message}finally{if(scope.valid())busy.value=false}}
async function remove(){if(!chat.value||running.value||busy.value)return;const scope=capture();busy.value=true;try{await api(root+'?expectedVersion='+chat.value.version,{method:'DELETE'});if(scope.valid()){await cacheSet(slot.value,null);chat.value=undefined;deleting.value=false;notice.value='这段对话已删除，来源世界及其他对话保持原状。'}}catch(e){if(scope.valid())error.value=(e as Error).message}finally{if(scope.valid())busy.value=false}}
async function exportText(){const scope=capture();try{const result=await api<{text:string;name:string}>(root+'/transcript');if(!scope.valid())return;const url=URL.createObjectURL(new Blob([result.text],{type:'text/plain;charset=utf-8'}));const link=document.createElement('a');link.href=url;link.download=result.name.replace(/[\\/:*?"<>|]/g,'_')+'.txt';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}catch(e){if(scope.valid())error.value=(e as Error).message}}
async function onPersonaUpdated(){await fetchChat()}
async function exportChat(){if(!chat.value||exporting.value)return;const scope=capture();exporting.value=true;error.value='';try{const blob=await authorizedBlob(root+'/export?format=jsonl');if(!scope.valid()||disposed)return;saveBlob(blob,safeFileName(chat.value.name||chat.value.characterName||'world-chat')+'.jsonl');notice.value='聊天记录已导出为 JSONL。'}catch(e){if(scope.valid()&&!disposed)error.value=(e as Error).message}finally{if(scope.valid()&&!disposed)exporting.value=false}}
async function openMemory(sequenceArg?:number){if(!chat.value||injectionLoading.value)return;const scope=capture();memoryOpen.value=true;injectionLoading.value=true;injectionError.value='';injection.value=null;const last=chat.value.messages?.length?chat.value.messages[chat.value.messages.length-1].sequence:0;const sequence=sequenceArg??last;memoryBefore.value=sequence;try{injection.value=await api<ChatInjection>(root+'/injection?before='+sequence);if(!scope.valid()||disposed)return}catch(e){if(scope.valid()&&!disposed)injectionError.value=(e as Error).message||'暂时无法查看本轮记忆。'}finally{if(scope.valid()&&!disposed)injectionLoading.value=false}}
function changeMemoryBefore(event:Event){const value=Number((event.target as HTMLSelectElement|null)?.value);if(Number.isFinite(value)&&value>0)void openMemory(value)}
async function searchMessages(){const scope=capture();searching.value=true;try{const result=await api<{items:ChatMessage[]}>(root+'/messages?q='+encodeURIComponent(messageSearch.value));if(scope.valid())matches.value=result.items}catch(e){if(scope.valid())error.value=(e as Error).message}finally{if(scope.valid())searching.value=false}}

function keyboard(event:KeyboardEvent){if(event.key==='Enter'&&(event.ctrlKey||event.metaKey)){event.preventDefault();void send()}}
function resume(){if(chat.value?.pendingTaskId)schedule(0);else void load()}
async function locateSource(){const sequence=Number(route.query.message);if(!Number.isSafeInteger(sequence)||sequence<1)return;const check=capture();try{const result=await api<{items:ChatMessage[]}>(root+'/messages?around='+sequence);if(check.valid()&&!disposed){matches.value=result.items;sourceOpen.value=true;locatedSequence.value=sequence;notice.value='已定位第 '+sequence+' 条附近的原消息；这些消息不会写入主线。';await nextTick();if(check.valid()&&!disposed)document.getElementById('chat-source-message-'+sequence)?.scrollIntoView({block:'center'})}}catch(e){if(check.valid())error.value=(e as Error).message}}
watch(()=>route.query.message,()=>{settings.value=false;if(chat.value?.pendingTaskId)schedule(0);void locateSource()})
onMounted(()=>{void load();window.addEventListener('reader-resume',resume);window.addEventListener('online',resume)})
onUnmounted(()=>{disposed=true;clearTimeout(timer);window.removeEventListener('reader-resume',resume);window.removeEventListener('online',resume)})
</script>
<template><WorldAppearanceProvider :world-id="chat?.worldId" :line-id="chat?.lineId" account><div class="workspace-page world-chat-page"><PageHeader :title="chat?.name||'角色独立对话'" eyebrow="我的对话" description="与人物单独聊聊，主线的时间、物品和结局保持原状。"><ModelControlButton v-if="chat" ref="modelButton" kind="chats" :identity="chat.id" @open="settings=true"/><button :disabled="!chat||busy||!app.online" @click="backup=true">导出聊天与记忆</button><button :disabled="!chat||running||busy" @click="renaming=true">修改名称</button><button :disabled="!chat||busy" @click="exportText">导出对话文本</button><button :disabled="!chat||exporting" @click="exportChat">{{exporting?'正在导出…':'导出聊天'}}</button><button :disabled="!chat" @click="openMemory()">本轮记忆</button><button :disabled="!chat||running||busy" @click="archive">{{chat?.status==='archived'?'恢复对话':'归档对话'}}</button><button class="danger" :disabled="!chat||running||busy" @click="deleting=true">删除这段对话</button></PageHeader><p v-if="error" class="error" role="alert">{{error}} <button :disabled="busy" @click="load">重新连接</button></p><p v-if="notice" role="status">{{notice}}</p><RouterLink v-if="!chat&&notice" to="/characters">返回角色卡库</RouterLink><p v-if="!chat&&!error&&!notice" role="status">正在读取独立对话…</p><div v-if="chat" class="world-chat-persona"><PersonaControl v-model="personaId" :session-id="chat.id" :version="chat.version" compact @updated="onPersonaUpdated"/></div><template v-if="chat"><section class="world-chat-source"><div><div class="chat-speaker"><CharacterAvatar :entity-id="chat.characterId" :name="chat.characterName"/><strong>{{chat.characterName}}</strong></div><p>{{chat.worldTitle}} · {{chat.snapshot.lineName}} · {{chat.snapshot.timeLabel}}</p><small>人物资料固定在开始聊天时的进度；新主线进展需要手动更新。</small></div><div class="world-chat-actions"><RouterLink :to="sourceLink" class="inline-link">返回主线</RouterLink><button :disabled="running||busy||!app.online" @click="previewSource"><RefreshCw :size="16"/>更新人物来源</button></div></section><details :open="sourceOpen" @toggle="sourceOpen=($event.target as HTMLDetailsElement).open"><summary>搜索与来源消息</summary><form @submit.prevent="searchMessages"><label>消息关键词<input v-model="messageSearch" maxlength="100" required></label><button :disabled="searching">搜索历史消息</button></form><p v-if="messageSearch&&!searching&&!matches.length">没有匹配的消息。</p><article v-for="m in matches" :key="m.id" :id="'chat-source-message-'+m.sequence" :class="{'chat-source-target':locatedSequence===m.sequence}"><small>第 {{m.sequence}} 条 · {{m.role==='user'?'你':chat.characterName}}</small><p style="white-space:pre-wrap">{{m.text}}</p></article></details><section ref="log" class="world-chat-log" role="log" aria-label="独立聊天记录" aria-live="polite" :style="readingStyle"><button v-if="chat.messages?.length&&chat.messages[0].sequence>1" @click="older">查看更早的消息</button><div v-if="!chat.messages?.length&&!running" class="empty"><h2>和 {{chat.characterName}} 打个招呼</h2><p>{{chat.snapshot.character.description}}</p><p>这里的谈话只保存在这段对话里。</p></div><article v-for="message in chat.messages" :key="message.id" class="world-chat-message" :class="message.role"><div class="chat-speaker"><AccountAvatar v-if="message.role==='user'"/><CharacterAvatar v-else :entity-id="chat.characterId" :name="chat.characterName"/><strong>{{message.role==='user'?'你':chat.characterName}}</strong></div><form v-if="editingSequence===message.sequence" class="world-chat-edit" @submit.prevent="saveEdit"><textarea v-model="editText" maxlength="4000" rows="3" aria-label="编辑这条消息" :disabled="editBusy"></textarea><div class="world-chat-edit-actions"><button type="submit" class="primary" :disabled="editBusy||!editText.trim()">{{editBusy?'正在保存…':'保存并重发'}}</button><button type="button" :disabled="editBusy" @click="cancelEdit">取消</button></div></form><p v-else>{{message.text||(message.role==='assistant'&&message.status==='pending'?'正在写…':'')}}</p><TaskProgress v-if="running&&message.status==='pending'" :progress="task?.progress"/><small v-if="message.role==='assistant'&&message.status!=='pending'">{{message.modelName}} · {{message.status==='interrupted'?'收到的部分回复':'已保存'}}</small><small v-if="message.role==='assistant'&&message.status==='pending'&&message.text">正在生成…</small><small v-if="message.checkpointId!==chat.checkpointId">来源：此前的故事进度</small><div v-if="forkSequence===message.sequence" class="world-chat-fork"><p>从第 {{message.sequence}} 条消息之后创建一条独立分支？原对话不会被改动。</p><div><button type="button" class="primary" :disabled="forking" @click="confirmFork">{{forking?'正在创建…':'确认分支'}}</button><button type="button" :disabled="forking" @click="cancelFork">取消</button></div></div><div v-if="editingSequence!==message.sequence&&!running&&!busy&&chat.status!=='archived'" class="world-chat-message-actions"><button v-if="message.role==='assistant'&&message.id===lastAssistantId" type="button" @click="regenerate">重新生成</button><button v-if="message.role==='user'" type="button" @click="startEdit(message)">编辑</button><button type="button" @click="askFork(message.sequence)">从这里分支</button></div></article><article v-if="running&&!pendingMessage" class="world-chat-message assistant"><div class="chat-speaker"><CharacterAvatar :entity-id="chat.characterId" :name="chat.characterName"/><strong>{{chat.characterName}}</strong></div><PublicStreamText v-if="task?.stream.text" :text="task.stream.text" :content-id="task.stream.contentId||task.id" :stream-version="task.stream.streamVersion||1"/><p v-else role="status">{{task?.persistenceState==='recoverable'?'正在恢复已收到的回复…':'正在思考…'}}</p><TaskProgress :progress="task?.progress"/></article></section><p v-if="chat.status==='archived'" role="status">这段对话已归档，恢复后可以继续发送。</p><form v-else class="world-chat-compose" @submit.prevent="send"><p v-if="intent&&!running" class="product-hint">上次发送结果尚未确认。重试会查询并继续同一条消息，不会重复发送。</p><label class="sr-only" for="world-chat-message">给人物的消息</label><textarea id="world-chat-message" v-model="draft" :disabled="busy||running||!!intent" maxlength="4000" rows="3" :placeholder="'想对 '+chat.characterName+' 说些什么？'" @keydown="keyboard"></textarea><div class="world-chat-actions"><small>{{!app.online?'离线 · 输入已保留':'独立对话 · 不改变主线状态'}}</small><button v-if="running" type="button" @click="stop"><Square :size="18"/>停止回复</button><button v-else class="primary" :disabled="busy||!app.online||!draft.trim()&&!intent" type="submit"><ArrowUp :size="18"/>{{intent?'重试发送':busy?'正在发送…':'发送'}}</button></div></form></template><Sheet v-if="memoryOpen" title="本轮记忆" @close="memoryOpen=false"><label class="world-chat-memory-pick">查看哪条消息之前的注入<select :value="String(memoryBefore)" @change="changeMemoryBefore"><option v-for="message in chat?.messages||[]" :key="message.sequence" :value="String(message.sequence)">第 {{message.sequence}} 条{{message.role==='assistant'?'回复':'消息'}}</option></select></label><p v-if="injectionLoading" role="status">正在读取本轮注入内容…</p><p v-if="injectionError" class="error" role="alert">{{injectionError}}</p><template v-if="injection"><p><strong>你的身份：</strong>{{injection.persona?.name||'未选择人设'}}</p><h3>命中的世界书</h3><p v-if="!injection.lore.length" class="product-hint">本轮没有命中世界书条目。</p><ul v-else><li v-for="item in injection.lore" :key="item.id||item.title">{{item.title}}</li></ul><h3>长期记忆</h3><p v-if="!injection.memories.length" class="product-hint">本轮没有注入长期记忆。</p><ul v-else><li v-for="item in injection.memories" :key="item.id||item.title">{{item.title}}<small> · {{item.kind}}</small></li></ul><p class="product-hint">这里展示的是上一轮回复前实际注入的内容；修改世界书、记忆或人设后会在下一轮生效。</p></template><p v-else-if="!injectionLoading&&!injectionError" class="product-hint">还没有可展示的注入内容。</p></Sheet><Sheet v-if="deleting&&chat" title="删除这段对话" @close="deleting=false"><p>删除本对话的所有消息和手动记忆，无法撤销。来源世界、主线进度及其他对话保持原状；已导出的备份由你保管。</p><button :disabled="busy" @click="deleting=false">保留对话</button><button class="danger" :disabled="busy||running" @click="remove">确认删除</button></Sheet><Sheet v-if="backup&&chat" title="导出聊天与记忆" @close="backup=false"><p>随来源故事一起保存全部独立聊天与记忆，恢复后可以从相同时间点继续对话。下载的文件可在“账号设置 → 数据与备份”中导入。</p><PrivateBackup mode="export" :story-id="'world-'+chat.worldId"/></Sheet><Sheet v-if="settings&&chat" title="对话模型与记忆" @close="closeSettings"><PlaySettings ref="modelSettings" @saved="modelButton?.refresh()" kind="chats" :identity="chat.id"/><div style="margin-top:16px"><ReadingPreferencePanel/></div></Sheet><Sheet v-if="sourceConfirm&&chat" title="更新人物来源" @close="sourceConfirm=false"><p v-if="sourcePreview">{{sourcePreview.fromTime}} → {{sourcePreview.toTime}} · {{sourcePreview.changed?'来源将前进':'当前已是这个时间点'}}</p><ul v-if="sourcePreview?.addedFacts.length"><li v-for="fact in sourcePreview.addedFacts" :key="fact.title">新增已知：{{fact.title}}</li></ul><p>以后发送的消息会使用当前主线进度中的人物资料与已知事实。之前的聊天记录保留原来源，聊天内容仍不会写回主线。</p><button class="primary" :disabled="running||busy" @click="update(true)">确认更新来源</button></Sheet><Sheet v-if="renaming&&chat" title="修改对话名称" @close="renaming=false"><label>对话名称<input aria-label="对话名称" v-model="name" maxlength="120"></label><button class="primary" :disabled="running||busy||!name.trim()" @click="update(false)">保存名称</button></Sheet></div></WorldAppearanceProvider></template>
<style scoped>.chat-speaker{display:flex;align-items:center;gap:10px;white-space:normal}.chat-source-target{border:2px solid var(--accent);border-radius:12px;padding:16px;background:var(--wash)}.world-chat-page{max-width:1120px}.world-chat-persona{margin:14px 0} .world-chat-memory-pick{display:grid;gap:8px;margin:0 0 16px}.world-chat-persona:empty{display:none}.world-chat-source{display:flex;justify-content:space-between;gap:16px;padding:20px;border:1px solid var(--edge);border-radius:14px;background:var(--paper)}.world-chat-source p{margin:8px 0}.world-chat-actions{display:flex;gap:12px;align-items:center;justify-content:space-between;flex-wrap:wrap}.world-chat-log{height:clamp(300px,52dvh,750px);overflow:auto;overscroll-behavior:contain;padding:24px 4px;scrollbar-gutter:stable}.world-chat-message{padding:18px 22px;margin:16px 0;max-width:85%;border:1px solid var(--edge);border-radius:14px;overflow-wrap:anywhere;white-space:pre-wrap;background:var(--paper)}.world-chat-message.user{margin-left:auto;background:var(--wash)}.world-chat-message small{color:var(--quiet);display:block;font-size:12px}.world-chat-message p{line-height:1.9}.world-chat-message-actions{display:flex;gap:8px;margin-top:8px}.world-chat-message-actions button{min-height:36px;padding:4px 12px;font-size:12px;border:1px solid var(--edge);border-radius:8px;background:var(--canvas);color:var(--quiet);cursor:pointer}.world-chat-message-actions button:hover{border-color:var(--accent);color:var(--accent)}.world-chat-fork{margin-top:10px;padding:10px 12px;border:1px dashed var(--edge);border-radius:10px;background:var(--wash)}.world-chat-fork p{margin:0 0 8px;font-size:13px;line-height:1.6}.world-chat-edit{display:grid;gap:8px}.world-chat-edit textarea{width:100%;min-height:72px;border:1px solid var(--edge);border-radius:10px;padding:10px;background:var(--canvas);color:var(--ink);resize:vertical}.world-chat-edit-actions{display:flex;gap:8px}.world-chat-edit-actions button{min-height:38px;padding:4px 14px;font-size:13px}.world-chat-compose{padding:16px;background:var(--paper);border:1px solid var(--edge);border-radius:14px;margin-bottom:env(safe-area-inset-bottom)}.world-chat-compose textarea{width:100%;resize:vertical;min-height:88px;border:0;background:transparent}.world-chat-page button{min-height:44px}.world-chat-page input{width:100%}.sr-only{position:absolute;width:1px;height:1px;overflow:hidden;clip-path:inset(50%)}@media(max-width:767px){.world-chat-source{display:block;padding:14px}.world-chat-source .world-chat-actions{margin-top:12px}.world-chat-message{max-width:94%;padding:14px}.world-chat-log{height:45dvh;min-height:280px}.world-chat-compose{padding:12px}}</style>
